-- OPENBRAIN-168: the Penfield case cabinet becomes the ring binder (Widget
-- Library Figma, page 1.2, "Binder" frames), as an uploaded widget.
--
-- 1. The widget upload `history-penfield-binder`, published, History colour
--    (fund). The HTML is src/widgets/uploads/history-penfield-binder.html
--    (Studio checks run in widgetUploads.test.js; this file must equal it,
--    historyPenfieldBinder.sql.test.js).
-- 2. The Penfield widget block in box-penfield points at the upload instead of
--    the Vue cabinet, and says itself that it is one screen of the chapter
--    (`fullScreen`), so that no longer comes from a code placement. Its
--    title, blurb, credit and placementId stay; `route` (the Vue cabinet's
--    own page) goes.
-- 3. The phrenology block gets the same `fullScreen`, for the same reason.
--
-- Push after the code that reads `fullScreen` from a block is deployed.
-- Idempotent: the upload upserts by slug; a block is changed only while it
-- still shows the cabinet, or still lacks the flag. No BEGIN/COMMIT.
--
-- To go back to the Vue cabinet, one update:
--   update public.paragraphs p set content = jsonb_set(p.content, '{blocks}', (
--     select jsonb_agg(case when b->>'widgetId' = 'upload:history-penfield-binder'
--       then b || '{"widgetId":"case-cabinet","route":"/case-cabinet"}'::jsonb else b end order by o)
--     from jsonb_array_elements(p.content->'blocks') with ordinality as x(b, o)))
--   where p.content->'blocks' @> '[{"widgetId":"upload:history-penfield-binder"}]'::jsonb;

insert into public.widget_uploads (slug, title, description, author, ramp, html, status)
values (
  'history-penfield-binder',
  $t$Penfield's case binder$t$,
  $t$Seven of Penfield and Perot's patients in a ring binder: open a case, touch the probe to a numbered point on the brain map and read what the patient reported.$t$,
  $t$Stuart Trenholm · design: Malpeso Studio$t$,
  'fund',
  $w$<!doctype html>
<!--
  Open Brain widget
  Title:    Penfield's case binder
  Chapter:  History (Foundations of Neuroscience), Box "Wilder Penfield and the Montreal Procedure"
  Author:   Stuart Trenholm · Design: Malpeso Studio (Widget Library Figma, page 1.2, "Binder" frames 107:56–107:1052)
  Version:  1 (2026-11-10)
  Changes:  First version. Replaces the case cabinet (the Vue view) with the ring binder:
            a cover, seven patient tabs, the stimulation map with the probe, and the report.
            Motion: the cover and the pages turn on the rings as real leaves, the probe
            travels to a point and touches it, rings spread, and the report is typed on.
  Sources:  Penfield W, Perot P. The brain's record of auditory and visual experience:
            a final summary and discussion. Brain 1963;86:595–696. Case text, maps and
            point positions are the book's verified appendix data
            (src/data/history/penfieldAppendix.json), unchanged.
  To check: 1. The typed letter behind the map is a design placeholder (a 1922 family
               letter from California, not a Penfield document). Replace or remove it.
            2. The photograph needs a caption, a source and a credit.
            3. Case 32, point 4: the design marks it on the map at the small mark between
               16 and 3. The verified data had no position for it. Confirm, or remove
               EXTRA_HOTSPOTS below and it is listed without a place on the map.
            4. Case 24, point 16 is not printed on the map; it is in the list only.
            5. Title kept as the chapter has it (the Figma says "Be Penfield").

  How it is put together: the code is first; the case data and the images sit at the
  end of the file in two <script type="application/json"> blocks. The maps are the
  book's scans with the outside of each brain made clear, so the sheet shows through.
-->
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Penfield's case binder</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;700&family=IBM+Plex+Sans:wght@400;500&display=swap"
      rel="stylesheet"
    />
    <style>
      /* The book sets the --ob-* tokens; the fallbacks make the file work on its own. */
      :root {
        --accent: var(--ob-accent, #8d4cf6);
        --plate: var(--ob-plate, #1c1c1c);
        --on: var(--ob-on-plate, #ffffff);
        --mute: var(--ob-on-plate-mute, rgba(255, 255, 255, 0.62));
        --sans: var(--ob-font-sans, "IBM Plex Sans", system-ui, sans-serif);
        --mono: var(--ob-font-mono, "IBM Plex Mono", ui-monospace, monospace);
        /* The binder's own paper colours (Figma) */
        --page: #e0ded3;
        --sheet: rgba(201, 198, 182, 0.95);
        --ink: #1c1c1c;
      }
      * {
        box-sizing: border-box;
      }
      html,
      body {
        margin: 0;
        background: var(--plate);
        color: var(--on);
        font-family: var(--sans);
      }
      .w {
        position: relative;
        max-width: 1440px;
        margin: 0 auto;
        padding: 20px 16px 16px;
        display: grid;
        gap: 16px;
      }
      .head {
        display: grid;
        gap: 8px;
        justify-items: center;
        text-align: center;
      }
      h1 {
        margin: 0;
        max-width: 30em;
        font: 500 clamp(24px, 4.2vw, 36px) / 1.25 var(--sans);
        letter-spacing: 0.5px;
      }
      .hint {
        margin: 0;
        max-width: 32em;
        font: 400 clamp(16px, 2.2vw, 20px) / 1.35 var(--sans);
        letter-spacing: 0.5px;
        color: #eceae4;
      }
      .cap {
        margin: 0;
        max-width: 48em;
        font: 400 12px/1.25 var(--mono);
        letter-spacing: 0.06em;
        color: var(--on);
      }
      button {
        font: inherit;
        color: inherit;
      }
      button:focus-visible {
        outline: 2px solid var(--accent);
        outline-offset: 2px;
      }

      /* ── The binder. Everything is laid out in the Figma frame's pixels and
         scaled by --s (set from the space there is); text keeps a readable
         size whatever the scale. Origin: the left page's top left corner. */
      .stage {
        position: relative;
        display: grid;
        place-items: center;
        min-width: 0;
        min-height: 0;
      }
      .binder {
        --s: 1;
        --u: calc(var(--s) * 1px);
        position: relative;
        flex: none;
        width: calc(944 * var(--u));
        height: calc(698 * var(--u));
        transform: translateX(calc(-16 * var(--u)));
        perspective: calc(4200 * var(--u));
      }
      /* Slides across as it opens, but not while it is first laid out. */
      .binder[data-ready] {
        transition: transform 0.76s cubic-bezier(0.45, 0.05, 0.25, 1);
      }
      /* Closed: only the cover and its tabs show, so they sit in the middle. */
      .binder[data-open="false"] {
        transform: translateX(calc(-255 * var(--u)));
      }
      .page {
        position: absolute;
        top: 0;
        height: 100%;
        background: var(--page);
        z-index: 1;
      }
      .page--left {
        left: 0;
        width: calc(472 * var(--u));
        transform-origin: 100% 50%;
      }
      .page--right {
        left: calc(476 * var(--u));
        width: calc(468 * var(--u));
      }
      .binder[data-open="false"] .page--left {
        visibility: hidden;
      }

      /* The cover: the journal's front matter, as the designer set it. */
      .cover {
        position: absolute;
        left: calc(476 * var(--u));
        top: 0;
        width: calc(468 * var(--u));
        height: 100%;
        z-index: 4;
        background: var(--page);
        box-shadow: inset 0.5px 0 0 rgba(0, 0, 0, 0.2);
        transform-origin: 0 50%;
        transition: transform 0.35s cubic-bezier(0.2, 0.7, 0.2, 1);
      }
      /* A tab under the pointer lifts the cover a little: it opens. */
      .binder[data-open="false"]:has(.tab:hover, .tab:focus-visible) .cover {
        transform: rotateY(-7deg);
      }
      .cover img {
        display: block;
        width: 100%;
        height: 100%;
      }
      .binder[data-open="true"] .cover {
        visibility: hidden;
      }

      /* Rings: the back half behind the pages, the front arc and the holes
         over them. */
      .ring {
        position: absolute;
        left: calc(452 * var(--u));
        top: calc((var(--y) - 10) * var(--u));
        width: calc(44 * var(--u));
        height: calc(20 * var(--u));
        pointer-events: none;
        overflow: visible;
      }
      .ring--back {
        z-index: 0;
      }
      .ring--front {
        z-index: 6;
      }

      /* Tabs: one per patient. Cases already turned past sit on the left. */
      .tabs {
        display: contents;
      }
      .tab {
        position: absolute;
        top: calc((35 + var(--i) * 90.63) * var(--u));
        left: calc(934 * var(--u));
        width: calc(42 * var(--u));
        height: calc(86.63 * var(--u));
        z-index: 3;
        padding: 0;
        border: 0;
        background: none;
        cursor: pointer;
        transition:
          width 0.15s ease-out,
          transform 0.15s ease-out;
      }
      .tab__b {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        background: var(--c);
        border-radius: 0 calc(6 * var(--u)) calc(6 * var(--u)) 0;
        overflow: hidden;
      }
      .tab__t {
        writing-mode: vertical-rl;
        font: 400 max(10px, calc(16 * var(--u))) / 1 var(--mono);
        letter-spacing: -0.05em;
        color: #000;
        white-space: nowrap;
      }
      .tab__t b {
        font-weight: 700;
      }
      .binder[data-compact] .tab__n {
        display: none;
      }
      .tab:hover,
      .tab:focus-visible {
        width: calc(52 * var(--u));
      }
      .tab:active .tab__b {
        filter: brightness(0.92);
      }
      .tab.is-left {
        left: calc(-28 * var(--u));
      }
      .tab.is-left:hover,
      .tab.is-left:focus-visible {
        transform: translateX(calc(-10 * var(--u)));
      }
      .tab.is-left .tab__b {
        border-radius: calc(6 * var(--u)) 0 0 calc(6 * var(--u));
      }
      .tab.is-left .tab__t {
        transform: rotate(180deg);
      }
      /* The open case's tab reaches onto its page. */
      .tab[aria-pressed="true"]::before {
        content: "";
        position: absolute;
        top: 0;
        bottom: 0;
        right: 100%;
        width: calc(14 * var(--u));
        background: color-mix(in srgb, var(--c) 32%, #fff);
        box-shadow: 0 1px 1px rgba(0, 0, 0, 0.2);
        opacity: 0.9;
      }

      /* Left page: the map on its sheet, things tucked behind it, the note. */
      .sheet {
        position: absolute;
        left: calc(14 * var(--u));
        top: calc(15 * var(--u));
        width: calc(455 * var(--u));
        height: calc(var(--sheet-h, 450) * var(--u));
        z-index: 3;
        background: var(--sheet);
        box-shadow: 0 1px 1px rgba(0, 0, 0, 0.2);
        transition: height 0.3s ease-out;
      }
      .map {
        position: absolute;
        left: calc(var(--mx) * var(--u));
        top: calc(var(--my) * var(--u));
        width: calc(var(--mw) * var(--u));
        height: calc(var(--mh) * var(--u));
      }
      .map img {
        display: block;
        width: 100%;
        height: 100%;
        user-select: none;
        -webkit-user-drag: none;
      }
      /* A stimulation point: a patch of the case's colour over the printed
         number. Points can be closer together than a finger, so the map
         takes the click and picks the nearest one (the list on the right
         page has a full-size button for each). */
      .mk {
        position: absolute;
        width: 0;
        height: 0;
        pointer-events: none;
        mix-blend-mode: multiply;
      }
      .mk i {
        position: absolute;
        left: 0;
        top: 0;
        width: calc(20 * var(--u));
        height: calc(20 * var(--u));
        border-radius: 50%;
        background: var(--c);
        opacity: 0.5;
        transform: translate(-50%, -50%);
        transition:
          width 0.2s ease-out,
          height 0.2s ease-out,
          opacity 0.2s ease-out;
      }
      .mk[data-near] i {
        opacity: 0.85;
      }
      .mk[data-on] i {
        width: calc(31 * var(--u));
        height: calc(31 * var(--u));
        opacity: 1;
      }
      .map[data-near] {
        cursor: pointer;
      }

      /* The photograph and the letter: loose in the binder, behind the sheet
         until the reader pulls one out. */
      .eph {
        position: absolute;
        left: calc(var(--cx) * var(--u));
        top: calc(var(--cy) * var(--u));
        width: calc(var(--w) * var(--u));
        z-index: var(--z, 1);
        padding: 0;
        border: 0;
        background: none;
        cursor: grab;
        touch-action: none;
        transform: translate(-50%, -50%)
          translate(calc(var(--dx, 0) * var(--u)), calc(var(--dy, 0) * var(--u)))
          rotate(var(--rot, 0deg));
      }
      .eph img {
        display: block;
        width: 100%;
        height: auto;
        filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.25));
        user-select: none;
        -webkit-user-drag: none;
        pointer-events: none;
        transition:
          transform 0.22s cubic-bezier(0.2, 0.8, 0.3, 1.3),
          filter 0.22s ease-out;
      }
      .eph:hover img,
      .eph:focus-visible img {
        transform: scale(1.02);
        filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.3));
      }
      /* Picked up: it comes off the page and straightens a little. */
      .eph.is-drag img {
        transform: scale(1.05) rotate(calc(var(--rot, 0deg) * -0.35));
        filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.35));
      }
      .eph.is-drag {
        cursor: grabbing;
      }
      .page--left[data-tall] .eph {
        display: none;
      }

      .note {
        --n: max(var(--s), 0.95);
        position: absolute;
        left: max(calc(94 * var(--u)), calc(79px * var(--n) + 18 * var(--u)));
        top: calc(37 * var(--u));
        width: calc(158px * var(--n));
        min-height: calc(70px * var(--n));
        z-index: 20;
        display: grid;
        align-content: center;
        padding: calc(12px * var(--n)) calc(12px * var(--n)) calc(8px * var(--n))
          calc(14px * var(--n));
        background: #fff;
        color: rgba(0, 0, 0, 0.62);
        font: 400 max(11px, calc(10px * var(--n))) / 1.25 var(--mono);
        letter-spacing: 0.1px;
        transform: translate(-50%, -50%) rotate(-10.11deg);
        pointer-events: none;
      }
      .note svg {
        position: absolute;
        left: 38%;
        top: calc(-9px * var(--n));
        width: calc(10px * var(--n));
        height: calc(29px * var(--n));
      }

      /* Penfield's probe: its tip rests on the chosen point. */
      .probe {
        position: absolute;
        left: 0;
        top: 0;
        width: 0;
        height: 0;
        z-index: 30;
        pointer-events: none;
        transition:
          transform 0.45s cubic-bezier(0.3, 0.1, 0.2, 1),
          opacity 0.2s ease-out;
      }
      .probe img {
        position: absolute;
        width: calc(340.6 * var(--u));
        height: calc(340.6 * var(--u));
        left: calc(-0.0584 * 340.6 * var(--u));
        top: calc(-0.1131 * 340.6 * var(--u));
        max-width: none;
        transform-origin: 5.84% 11.31%;
        transform: rotate(-101.79deg);
        filter: drop-shadow(calc(3 * var(--u)) calc(4 * var(--u)) calc(3 * var(--u)) rgba(0, 0, 0, 0.25));
        transition:
          transform 0.16s cubic-bezier(0.3, 0, 0.2, 1.5),
          filter 0.16s ease-out;
      }
      /* Held above the page while it travels; it touches down on the point. */
      .probe.is-air img {
        transform: translateY(calc(-7 * var(--u))) rotate(-101.79deg) scale(1.03);
        filter: drop-shadow(calc(9 * var(--u)) calc(14 * var(--u)) calc(8 * var(--u)) rgba(0, 0, 0, 0.26));
        transition-duration: 0.3s;
        transition-timing-function: ease-out;
      }
      /* The stimulation: rings spread from the point the probe touches. */
      .pulse {
        position: absolute;
        width: calc(31 * var(--u));
        height: calc(31 * var(--u));
        border: max(1.5px, calc(2.5 * var(--u))) solid var(--c);
        border-radius: 50%;
        pointer-events: none;
      }
      .probe[data-off] {
        opacity: 0;
      }

      /* Right page: the report. */
      .paper {
        position: absolute;
        left: calc(3 * var(--u));
        top: calc(15 * var(--u));
        width: calc(455 * var(--u));
        height: calc(670 * var(--u));
        background:
          linear-gradient(270deg, rgba(255, 255, 255, 0.5) 62.5%, rgba(232, 232, 232, 0.25) 100%),
          #fff;
        box-shadow: 0 1px 1px rgba(0, 0, 0, 0.2);
        color: var(--ink);
        overflow: hidden;
      }
      .read {
        position: absolute;
        inset: 0;
        display: flex;
        flex-direction: column;
        padding: calc(78 * var(--u)) calc(45 * var(--u)) calc(20 * var(--u)) calc(50 * var(--u));
      }
      .read h2 {
        flex: none;
        margin: 0 0 calc(28 * var(--u));
        font: 700 max(20px, calc(30 * var(--u))) / 0.95 var(--mono);
        letter-spacing: 0.1px;
        text-transform: uppercase;
        color: #1b1b1b;
      }
      .read h2 span {
        display: block;
        width: fit-content; /* typed on, a letter at a time */
      }
      /* The report waits for the probe to touch the point. */
      .read[data-wait] h2 > span,
      .read[data-wait] .report > * {
        visibility: hidden;
      }
      .report {
        flex: 1;
        min-height: 3.5em;
        overflow-y: auto;
        scrollbar-width: thin;
        scrollbar-color: rgba(0, 0, 0, 0.35) transparent;
      }
      /* More to read below: the last lines fade. */
      .report[data-more] {
        -webkit-mask-image: linear-gradient(#000 calc(100% - 32px), transparent);
        mask-image: linear-gradient(#000 calc(100% - 32px), transparent);
      }
      .report p {
        margin: 0 0 1.4em;
        font: 400 max(13px, calc(13 * var(--u))) / 1.4 var(--mono);
        letter-spacing: 0.1px;
      }
      .report p:last-child {
        margin-bottom: 0.4em;
      }
      .report b {
        font-weight: 700;
      }
      .report .off-map {
        color: rgba(0, 0, 0, 0.62);
      }
      .pts {
        flex: none;
        margin-top: 12px;
        padding-top: 10px;
        border-top: 1px solid rgba(0, 0, 0, 0.16);
      }
      .pts__l {
        display: block;
        margin-bottom: 6px;
        font: 500 11px/1.3 var(--mono);
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: rgba(0, 0, 0, 0.62);
      }
      .pts__row {
        display: flex;
        flex-wrap: wrap;
        gap: 6px;
      }
      .pt {
        min-width: clamp(36px, calc(44 * var(--u)), 44px);
        min-height: clamp(36px, calc(44 * var(--u)), 44px);
        padding: 0 6px;
        border: 1px solid rgba(0, 0, 0, 0.4);
        background: transparent;
        color: var(--ink);
        font: 500 13px/1 var(--mono);
        cursor: pointer;
      }
      .pt:hover {
        background: rgba(0, 0, 0, 0.06);
      }
      .pt[aria-pressed="true"] {
        border-color: #000;
        background: var(--c);
        color: #000;
        font-weight: 700;
      }
      .read :focus-visible {
        outline: 2px solid #000;
        outline-offset: 2px;
      }

      /* The leaf that turns on the rings: the page it leaves on its front, the
         page it lands as on its back. Copies of the real pages, so the turn
         shows the real thing. */
      .leaf {
        position: absolute;
        top: 0;
        left: calc(474 * var(--u));
        width: calc(470 * var(--u));
        height: 100%;
        z-index: 5;
        transform-origin: 0 50%;
        transform-style: preserve-3d;
        pointer-events: none;
      }
      .leaf__face {
        visibility: visible;
        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
        transform: none;
        transition: none;
      }
      .leaf__face--back {
        transform-origin: 50% 50%;
        transform: rotateY(180deg);
      }
      /* A page darkens as it turns edge on, most by the rings. */
      .leaf__shade {
        position: absolute;
        inset: 0;
        z-index: 60;
        opacity: 0;
        background: linear-gradient(90deg, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.18));
        pointer-events: none;
      }
      .leaf__face--back .leaf__shade {
        background: linear-gradient(270deg, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.18));
      }
      /* The page the leaf will cover keeps its old face until it lands. */
      .ghost {
        z-index: 2;
        pointer-events: none;
      }
      /* The leaf's shadow on the pages under it. */
      .cast {
        position: absolute;
        inset: 0;
        z-index: 4;
        opacity: 0;
        background: linear-gradient(
          90deg,
          rgba(0, 0, 0, 0) 12%,
          rgba(0, 0, 0, 0.28) 50%,
          rgba(0, 0, 0, 0) 88%
        );
        pointer-events: none;
      }

      /* ── Phones and narrow columns: the same binder as a stack. */
      .binder[data-layout="stack"] {
        display: grid;
        gap: 10px;
        width: calc(472 * var(--u));
        height: auto;
        transform: none;
        perspective: none;
      }
      .binder[data-layout="stack"] .ring,
      .binder[data-layout="stack"] .eph,
      .binder[data-layout="stack"] .leaf,
      .binder[data-layout="stack"] .ghost,
      .binder[data-layout="stack"] .cast {
        display: none;
      }
      .binder[data-layout="stack"] .tabs {
        display: flex;
        flex-wrap: wrap;
        gap: 4px;
      }
      .binder[data-layout="stack"] .tab {
        position: relative;
        top: auto;
        left: auto;
        width: auto;
        height: 44px;
        flex: 1 0 auto;
      }
      .binder[data-layout="stack"] .tab__b {
        position: relative;
        height: 100%;
        padding: 0 10px;
        border-radius: 6px 6px 0 0;
      }
      .binder[data-layout="stack"] .tab__t {
        writing-mode: horizontal-tb;
        transform: none;
        font-size: 14px;
        letter-spacing: -0.02em;
      }
      /* The open case's tab: ruled in ink (there is no page edge to reach onto). */
      .binder[data-layout="stack"] .tab[aria-pressed="true"]::before {
        content: none;
      }
      .binder[data-layout="stack"] .tab[aria-pressed="true"] .tab__b {
        box-shadow: inset 0 0 0 2px #000;
      }
      .binder[data-layout="stack"] .page,
      .binder[data-layout="stack"] .cover {
        position: relative;
        left: auto;
        width: 100%;
      }
      .binder[data-layout="stack"] .cover {
        aspect-ratio: 468 / 698;
        height: auto;
      }
      .binder[data-layout="stack"][data-open="true"] .cover,
      .binder[data-layout="stack"][data-open="false"] .page {
        display: none;
      }
      .binder[data-layout="stack"] .page--left {
        height: calc((var(--sheet-h, 450) + 30) * var(--u));
      }
      .binder[data-layout="stack"] .page--right {
        height: auto;
        padding: 10px;
      }
      .binder[data-layout="stack"] .paper,
      .binder[data-layout="stack"] .read {
        position: relative;
        inset: auto;
        left: auto;
        top: auto;
        width: auto;
        height: auto;
        overflow: visible;
      }
      .binder[data-layout="stack"] .read {
        display: block;
        padding: 24px 20px 20px;
      }
      .binder[data-layout="stack"] .report {
        overflow: visible;
        -webkit-mask-image: none;
        mask-image: none;
      }
      .binder[data-layout="stack"] .pt {
        min-width: 44px;
        min-height: 44px;
      }

      /* ── The photograph, large. */
      .lb {
        position: fixed;
        inset: 0;
        z-index: 100;
        display: grid;
        grid-template-rows: minmax(0, 1fr) auto;
        justify-items: center;
        align-items: center;
        gap: 12px;
        padding: 24px 24px 16px;
        background: rgba(28, 28, 28, 0.86);
      }
      .lb[hidden] {
        display: none;
      }
      .lb img {
        display: block;
        max-width: min(92%, 720px);
        max-height: 100%;
        min-height: 0;
        object-fit: contain;
      }
      .lb p {
        margin: 0;
        max-width: 40em;
        text-align: center;
        font: 400 12px/1.4 var(--mono);
        color: var(--mute);
      }
      .lb__x {
        position: absolute;
        top: 12px;
        right: 12px;
        width: 44px;
        height: 44px;
        display: grid;
        place-items: center;
        padding: 0;
        border: 0;
        background: none;
        color: #fff;
        cursor: pointer;
      }

      /* A fixed height (the full-screen band): the heading and caption keep
         their size, the binder takes what is left, nothing is cut. */
      html[data-ob-fit],
      html[data-ob-fit] body {
        height: 100%;
        overflow: hidden;
      }
      html[data-ob-fit] .w {
        height: var(--ob-max-height, 100%);
        grid-template-rows: auto minmax(0, 1fr) auto;
        gap: 10px;
        padding: 6px 16px 8px;
      }
      html[data-ob-fit] h1 {
        font-size: clamp(20px, 4.4vh, 36px);
      }
      html[data-ob-fit] .hint {
        font-size: clamp(14px, 2.5vh, 20px);
      }
      html[data-ob-fit] .head {
        gap: 4px;
      }
      /* A fixed height on a phone: the stacked binder is taller than one
         screen, so it scrolls inside its frame and nothing is cut. */
      html[data-ob-fit] .w[data-stack] {
        grid-template-rows: auto auto auto;
        align-content: start;
        overflow-y: auto;
        padding-top: 4px;
      }
      html[data-ob-fit] .w[data-stack] h1 {
        font-size: 24px;
      }
      html[data-ob-fit] .w[data-stack] .hint {
        font-size: 16px;
      }
      /* With room beside the binder the source line sits in the corner
         (as the Figma has it) and takes no height from the binder. */
      .w[data-cap="side"] .cap {
        position: absolute;
        left: 16px;
        bottom: 8px;
        max-width: var(--cap-w, 280px);
      }

      @media (prefers-reduced-motion: reduce) {
        * {
          transition: none !important;
          animation: none !important;
        }
      }
      html[data-ob-reduce-motion] * {
        transition: none !important;
        animation: none !important;
      }
    </style>
  </head>
  <body>
    <main class="w" id="w">
      <header class="head">
        <h1>Find out what it was like to be Dr. Wilder Penfield</h1>
        <p class="hint">
          Choose a patient’s case and explore what having your brain
          electrically stimulated by Penfield was like.
        </p>
      </header>

      <div class="stage" id="stage">
        <div class="binder" id="binder" data-open="false" data-layout="spread">
          <div class="tabs" id="tabs" role="group" aria-label="Patient cases"></div>

          <section class="page page--left" id="left" aria-label="Stimulation map">
            <div class="sheet" id="sheet">
              <div class="map" id="map"></div>
            </div>
            <p class="note" aria-hidden="true">
              <svg viewBox="0 0 10.24 29" aria-hidden="true">
                <path
                  transform="rotate(90) translate(0 -10.24)"
                  fill="#808080"
                  d="M25.6033 0.827603C27.0251 0.827603 28.1775 1.98727 28.1775 3.4179C28.1774 4.8484 27.025 6.0082 25.6033 6.0082H8.89935V6.8358H25.6033C27.4792 6.8358 28.9998 5.30548 29 3.4179C29 1.53019 27.4793 0 25.6033 0H5.14845C2.30502 0.000104083 0 2.31939 0 5.1806C8.99982e-05 7.65 1.71713 9.71584 4.01539 10.2353V9.38271C2.17583 8.88162 0.822554 7.19014 0.822467 5.1806C0.822467 2.77646 2.75926 0.827707 5.14845 0.827603H25.6033Z"
                />
              </svg>
              Select a number on the brain map or explore a different case.
            </p>
            <div class="probe" id="probe" data-off aria-hidden="true">
              <img id="probeImg" alt="" />
            </div>
          </section>

          <section class="page page--right" aria-label="What the patient reported">
            <div class="paper">
              <div class="read" id="read">
                <h2 id="readh" aria-live="polite"></h2>
                <div class="report" id="report" tabindex="0" role="region" aria-labelledby="readh" aria-live="polite"></div>
                <div class="pts">
                  <span class="pts__l" id="ptsl"></span>
                  <div class="pts__row" id="pts" role="group" aria-labelledby="ptsl"></div>
                </div>
              </div>
            </div>
          </section>

          <div class="cover" id="cover">
            <img
              id="coverImg"
              alt="Title page of the source: Brain, volume 86, part 4. The brain’s record of auditory and visual experience: a final summary and discussion, by Wilder Penfield and Phanor Perot. Macmillan, 1963. Two drawings of slices through the brain."
            />
          </div>
        </div>
      </div>

      <p class="cap" id="cap"></p>

      <div class="lb" id="lb" hidden role="dialog" aria-modal="true" aria-label="Photograph">
        <button type="button" class="lb__x" id="lbx" aria-label="Close">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">
            <path d="M2 2l16 16M18 2L2 18" />
          </svg>
        </button>
        <img id="lbimg" alt="" />
        <p id="lbcap"></p>
      </div>
    </main>

    <script id="cases" type="application/json">
      {"source":{"citation":"Excerpts from: The Brain’s Record of Auditory and Visual Experience - A Final Summary and Discussion, by Wilder Penfield and Phanor Perot. Brain, 1963."},"cases":[{"id":"rw","tab":"R.W.","caseNo":3,"image":{"width":576,"height":389},"points":[{"id":"22","events":[{"text":"22. He said nothing for a little interval, and then he said, \"Oh, gee, gosh, robbers are coming at me with guns!\" He heard nothing, he just saw them coming at him. The robbers seemed to have been coming at an angle from the left. When asked if they came in front of him, he said no they were behind him. This seems to be the reproduction not of a real event, but of a fantasy or a dream drawn from the reading of a comic book, a silent fantasy devoid of auditory components."}],"hotspots":[{"x":29.6875,"y":48.5861}]},{"id":"23","events":[{"text":"23. \"Pain in my forehead, and there was a robber. He wasn't in front, he was off to the left side.\""}],"hotspots":[{"x":37.8472,"y":71.7224}]},{"id":"24","events":[{"text":"24. \"Yes, the robbers, they are coming after me.\" "}],"hotspots":[{"x":15.7986,"y":34.4473}]},{"id":"28","events":[{"text":"28. \"Oh gosh! There they are, my brother is there. He is aiming an air rifle at me.\" His eyes moved slowly to the left. The figures seemed to disappear before the cessation of the stimulus. When asked, he said his brother was walking toward him, and the gun was loaded. When asked where he was, he said at his house, in the yard. His other little brother was there, that was all. When asked if he felt scared when he saw his brother, he said, \"Yes.\" When asked if he always felt scared when he saw the robbers, he said, \"Yes.\""}],"hotspots":[{"x":27.9514,"y":64.2674}]},{"id":"30","events":[{"text":"30. \"I heard someone speaking, my mother telling one of my aunts to come up tonight.\""}],"hotspots":[{"x":49.4792,"y":50.6427}]},{"id":"31","events":[{"text":"31. \"Would you do it again, please ?\""},{"text":"31. Repeated. After a pause, he said, \"The same as before. My mother was telling my aunt over the telephone to come up and visit us tonight.\" When asked how he knew she was talking over the telephone, he said he did not see her, but from the way his aunt's voice sounded when she answered he knew it was over the telephone."}],"hotspots":[{"x":40.9722,"y":45.7584}]},{"id":"32","events":[{"text":"32. \"My mother is telling my brother he has got his coat on backwards. I can just hear them.\" When asked if he remembered it, he said, \"Oh yes, just before I came here.\" When asked if he thought these things were like dreams, he said, \"No.\" When asked what it was like, he said, \"It is just like I go into a daze.\" "}],"hotspots":[{"x":44.7917,"y":48.5861}]}]},{"id":"abra","tab":"A. Bra.","caseNo":4,"image":{"width":640,"height":851},"points":[{"id":"15","events":[{"text":"15. \"I hear singing.\""},{"text":"15. Repeated. \"Yes, it is White Christmas.\" When asked if anyone was singing, she said, \"Yes, a choir.\" When asked if she remembered it being sung with a choir, she said she thought so."},{"text":"15. Repeated (26 minutes after last stimulation at 15). \"White Christmas,\" she said it was the orchestra playing."}],"hotspots":[{"x":46.875,"y":23.8543}]},{"id":"16","events":[{"text":"16. \"That is different, a voice—talking—a man.\""}],"hotspots":[{"x":51.0938,"y":25.0294}]},{"id":"17","events":[{"text":"17. \"Yes, 1 have heard it before. A man's voice—talking.\""},{"text":"17. Repeated without warning. \"Yes, about the same.\""},{"text":"17. Repeated (24 minutes after last stimulation at 17). \"Yes, the play again.\""}],"hotspots":[{"x":53.5938,"y":25.7344}]},{"id":"18","events":[{"text":"18. \"There is the sound again—like a radio program—a man talking.\" She said it was like a play, the same voice as before."},{"text":"18. Repeated (21 minutes after last stimulation at 18). \"White Christmas.\""}],"hotspots":[{"x":58.5938,"y":27.7321}]},{"id":"19","events":[{"text":"19. \"The play again!\" Then she began to hum. When asked what she was humming, she said she did not know, it was what she heard."},{"text":"19. Repeated. Patient began to hum. She continued at the ordinary pace of a song. \"I know it but I don't know the name—I have heard it before. I hear it, it is an instrument—just one.\" She thought it was a violin."}],"hotspots":[{"x":40.4688,"y":20.6816}]},{"id":"23","events":[{"text":"23. \"The play—they are talking.\" When asked who, she said, \"The men are talking.\" When asked who they were, she said, \"I don't know.\""}],"hotspots":[{"x":46.875,"y":26.792}]},{"id":"26","events":[{"text":"26. Patient said, \"It hurts.\" Stimulation was stopped. She said, \"I see a picture.\" She added, \"It was a face which comes from a picture.\""},{"text":"26. Repeated. \"Nothing.\""}],"hotspots":[{"x":51.7188,"y":85.0764}]},{"id":"27","events":[{"text":"27. \"The same thing. The play and they are banging on something like a drum.\""}],"hotspots":[{"x":43.75,"y":64.3948}]},{"id":"28","events":[{"text":"28. \"I see people walking.\" When asked where they are, she said, \"I think they are here.\" She said they were strangers."}],"hotspots":[{"x":39.2188,"y":64.3948}]}]},{"id":"yn","tab":"Y.N.","caseNo":12,"image":{"width":1298,"height":938},"points":[{"id":"26","events":[{"text":"26. \"I could hear someone talking, murmuring or something.\""}],"hotspots":[{"x":50.3082,"y":51.5991}]},{"id":"25","events":[{"text":"25. \"There was talking or murmuring, but I cannot understand it.\" Apparently this resembled the voices she heard before her attacks."}],"hotspots":[{"x":44.1448,"y":55.3305}]},{"id":"27","events":[{"text":"27. Silence, then a loud cry. \"I heard the voices and then I screamed. I had a feeling all over.\""},{"text":"27. Repeated thirteen minutes after last stimulation at this point. After a time the patient said that she was trying to hear what someone was saying, but she could not make it out. She said it was one man doing the talking."}],"hotspots":[{"x":58.6287,"y":47.1215}]},{"id":"28","events":[{"text":"28. \"I hear something.\" She did not see anything. The electrode was kept in place. When asked what she heard, she said, \"A buzzing-like.\" Then she added, \"A man buzzing or murmuring.\" When asked where he was she said, \"In the back.\""}],"hotspots":[{"x":61.3251,"y":43.9232}]},{"id":"33","events":[{"text":"33. She began to sob, \"That man's voice again! The only thing I know is that my father frightens me a lot.\""}],"hotspots":[{"x":54.5455,"y":49.3603}]}]},{"id":"gp","tab":"G.P.","caseNo":24,"image":{"width":1298,"height":840},"points":[{"id":"14","events":[{"text":"14. When the electrode was applied, the patient said, \"Wait a minute, I see someone.\" When asked, he said it was a man running."}],"hotspots":[{"x":33.9753,"y":56.0714}]},{"id":"15","events":[{"text":"15. He exclaimed, \"Oui, la, la, la. It was he, he came, that fool.\""}],"hotspots":[{"x":35.208,"y":51.4286}]},{"id":"16","events":[{"text":"16. Patient said, \"There, there, j'entend. It is just that somebody wanted to speak to me and he was going vite, vite, vite.\""}],"hotspots":[]}]},{"id":"sbe","tab":"S. Be.","caseNo":29,"image":{"width":1170,"height":1280},"points":[{"id":"14","events":[{"text":"14. \"Just like someone whispering, or something, in my left ear. It sounded something like a crowd.\" Warning was then given but no stimulation. He reported, \"Nothing.\""}],"hotspots":[{"x":52.4786,"y":32.7344}]},{"id":"15","events":[{"text":"15. \"Again someone trying to speak to me, a single person.\" When asked, he added, \"Oh, a man's voice, I could not understand what he said.\""}],"hotspots":[{"x":47.6068,"y":31.0938}]},{"id":"16","events":[{"text":"16. While the electrode was held in place the patient said, \"Something brings back a memory, I could see Seven-Up Bottling Company—Harrison Bakery.\" Warning was given again, but no stimulus applied. He was not fooled and replied, \"Nothing.\""}],"hotspots":[{"x":59.4872,"y":35.625}]},{"id":"17","events":[{"text":"17. While the electrode was held in place he replied, \"Again something ] have heard of but I cannot remember it.\" On questioning he added that it was a word but he could not remember what Word."}],"hotspots":[{"x":62.0513,"y":37.5781}]},{"id":"18","events":[{"text":"18. Stimulus was applied without warning the patient. He said he was a little drowsy, then, \"Someone was there in front of me right where the nurse is sitting.\""}],"hotspots":[{"x":54.4444,"y":36.1719}]},{"id":"19","events":[{"text":"19. During stimulation he said, \"I am trying to find the name of a song.\" The electrode was removed. \"There was a piano there and someone was playing. I could hear the song, you know. It is a song I have sung before but I cannot find out quite what the title of the song is. That was what I was trying to do when you finished stimulating!\""},{"text":"19. Repeated without warning. After withdrawal of the electrode, he said, \"Someone was speaking to another and he mentioned a name but I could not understand it.\" When asked whether he saw the person, he replied, \"It was just like a dream.\" When asked if the person was there he said, \"Yes, sir, about where the nurse with the eyeglasses is sitting over there.\""},{"text":"19. Repeated again without warning the patient, and without questioning him. \"Yes, 'Oh Marie, Oh Marie'—someone is singing it.\" He was then asked who it was and he replied, \"I don't know, Doctor, I cannot recognize the voice.\""},{"text":"19. Repeated again without warning. He observed, while the electrode was being held in place, \"Again, 'Oh Marie, Oh Marie.' \" He explained that he had heard this before. \"It is a theme song,\" he said, \"on a radio program. The program is called the 'Life of Luigi,' \" The patient then discussed the identity of the song with Dr. Sears and he ended by singing the well-known refrain, \"Oh Marie, Oh Marie.\" All in the operating room recognized the song."},{"text":"19. Repeated eight minutes after first stimulation at this point. Patient said, \"Nothing.\" This stimulation was preceded by stimulation just below this same point and he heard the singing."},{"text":"19. This point where the song had been produced earlier was restimulated several times near the end of the exploration but nothing was evoked."}],"hotspots":[{"x":44.5299,"y":29.6094}]},{"id":"21","events":[{"text":"21. \"Someone telling me in my left (contralateral) ear, 'Sylvere, Sylvere!' It could have been the voice of my brother.\""},{"text":"21. Repeated without warning. When asked after the stimulation, he said, \"I can- not make it out.\""},{"text":"21. Repeated thirty minutes after last stimulation at this point. \"Nothing.\""}],"hotspots":[{"x":46.0684,"y":37.7344}]},{"id":"23","events":[{"text":"23. During stimulation he said, \"It is a woman calling something, but I cannot make out the name.\""}],"hotspots":[{"x":48.7179,"y":34.8438}]},{"id":"24","events":[{"text":"24. Stimulation at a depth of 1 -5 cm. \"Somebody talking. I cannot make out who it was.\""}],"hotspots":[{"x":51.8803,"y":77.5781}]},{"id":"25","events":[{"text":"25. Stimulation at a depth of 1 cm. Patient said, \"Buzzing sound.\" When asked if there was anything else, he said, \"A man talking.\" (Auditory sensation and experiential response.)"}],"hotspots":[{"x":53.5897,"y":79.8438}]},{"id":"26","events":[{"text":"26. Stimulation without warning. \"There is someone near my left eye, but I cannot make it out\""},{"text":"26. Repeated without warning. \"Oh, my left eye! I see someone.\" Then he explained that there were men and women. \"They seemed to be sitting down and listening to someone. But I do not see who that someone might be.\""}],"hotspots":[{"x":33.2479,"y":42.5781}]},{"id":"27","events":[{"text":"27. During stimulation without warning he said, \"Yes, there was something.\" He said he saw it; it was an object. The operator noted that each of these visual experiences seemed to disappear before the end of stimulation."}],"hotspots":[{"x":43.4188,"y":32.1875}]},{"id":"28","events":[{"text":"28. Stimulation at a depth of 1 cm. \"A buzzing.\" Then the electrode was withdrawn slowly and he exclaimed, \"Someone is calling.\" He could not understand the words. (Here the electrode was in the anterior transverse temporal gyrus of Heschl and upon withdrawal the adjacent first temporal gyrus was stimulated)."}],"hotspots":[{"x":57.265,"y":41.4062}]},{"id":"29","events":[{"text":"29. \"I don't know—I see someone in front of me.\""},{"text":"29. Repeated without warning. \"I hear someone talking.\""}],"hotspots":[{"x":57.265,"y":81.4844}]}]},{"id":"nc","tab":"N.C.","caseNo":31,"image":{"width":1342,"height":886},"points":[{"id":"19","events":[{"text":"19. \"I had a dream. I had a book under my arm and 1 was talking to a man. The man was trying to reassure me not to worry about the book.\" When asked, she said she did not know what the book was or who the man was."},{"text":"19. Repeated without warning, twenty minutes after the previous stimulation at this point. When asked afterward if she had noticed anything, she said, \"I noticed I was having a dream, but I do not know what it was, it was crazy.\""},{"text":"19. Stimulation near point 19. \"Another dream, crazy.\""}],"hotspots":[{"x":39.8659,"y":74.4921}]},{"id":"20","events":[{"text":"20. Patient said, \"I feel like I have a sick spell.\" Stimulus was withdrawn. She then added that, \"Mother is talking to me.\""},{"text":"20. Repeated ten minutes later. Patient laughed. When asked what had happened, while stimulation was still going on, she said, \"Well, it is kind of a long story but I will tell you.\" Stimulus was withdrawn. She went on to explain a rather complicated situation, and then said she told her mother, \"Don't forget the fabulous feeling.\" When asked if that was something she had said to her mother, she said her mother mocked her. When asked whether it was a dream or something she remembered, she exclaimed, \"No.\" Then she said, \"I took my arm and brought it down on the plate and broke the plate all to pieces.\" When asked where it was, she said in her home in Richland, Washington."},{"text":"20. Repeated without warning. She said, \"Yes, another experience, a different experience.\" Then she added, \"A true experience. This man, Mr. Meerburger, he, oh well, he drinks. Twice his boy has run away. I went to the store once for an ice cream cone and I saw that he was back, and I said 'Hmm, he is back,' and the lady asked me 'What is the matter,' and I didn't know how to explain so I said, 'Well you know Mr. Meerburger drinks.' I thought that was the easiest way but later mother told me, no, and it made it a lot worse.\""},{"text":"20. Repeated seven minutes after previous stimulation at this point. \"Nothing.\""}],"hotspots":[{"x":43.6662,"y":69.0745}]},{"id":"23","events":[{"text":"23. \"It made me think of a baby song, I cannot think of the words.\""},{"text":"23. Repeated. \"I had a little pain in my head. I again thought of the song.\" When asked what song, she said, \"That baby song—the War March of the Priests.\" "},{"text":"23. Repeated without warning. After withdrawal, the operator said, \"You don't notice anything do you?\" She replied, \"Yes, I was trying to identify the song.\" When asked if she would like the stimulation repeated, she said, \"Yes.\" Stimulus was applied and after a time she began to hum, and she hummed an air quite accurately. Then she said, \"It is the War March of the Priests.\""},{"text":"23. Repeated. Patient was asked if she heard the air and she said she heard another one which sounded very much like \"War March of the Preiests.\" She added that it was not a baby song after all. She thought the first song she heard was a baby song."},{"text":"23. As a final test the patient was asked to let the operator know when she heard the song. After some delay, point 23 was stimulated. As the electrode was applied, she said, \"There.\" When asked what it was, she said all she could think of was the War March of the Priests. She said she had the Hallelujah Chorus on a record at home and that this was on the other side of it."}],"hotspots":[{"x":39.9404,"y":60.158}]}]},{"id":"ge","tab":"G.E.","caseNo":32,"image":{"width":1342,"height":886},"points":[{"id":"1b","events":[{"text":"1b. Electrode at a depth of 2 cm. Patient said she heard a buzzing sound. Then she said she saw a friend of hers. When asked who it was, she said \"Somebody I know who I met on the street.\" She said it was a man and that she sometimes sees people in her attacks."}],"hotspots":[{"x":24.9627,"y":63.8826}]},{"id":"1c","events":[{"text":"1c. After a pause the patient said, \"I see a machine, one that I have seen before.\" The machine seemed to disappear before the end of the stimulation."},{"text":"1c. Repeated eighteen minutes after last stimulation at this point \"I see the nurse.\" When asked afterwards, she said, \"It was a little dream.\" She saw the nurse just as she is now."}],"hotspots":[{"x":26.9001,"y":50.4515}]},{"id":"2b","events":[{"text":"2b. After stimulation was over she said, \"I saw a few people. Some of the nurses on the floor (she meant her hospital ward). I cannot describe it now.\" When asked, she said that in her attacks she sees mostly people."}],"hotspots":[{"x":36.4382,"y":68.2844}]},{"id":"3","events":[{"text":"3. \"Something new, I hear my mother singing.\" The electrode was replaced and she repeated, \"I hear my mother singing.\""},{"text":"3. Repeated without warning. After a little time, she said, \"1 hear my brother talking.\" When asked what he was saying, she said he was talking to one of his schoolmates."},{"text":"3. Repeated again without warning. \"I hear my mother and father talking and singing.\" And after a pause, \"Christmas carols.\" When asked, she said, \"I saw them for a second or two, then it faded.\" On further inquiry, she said they were talking and singing about Christmas. She was then asked if when she had heard her brother she also saw him and she replied, \"Yes.\""},{"text":"3. Repeated ten minutes after previous stimulation at this point. \"Nothing.\""},{"text":"3. Repeated. The electrode was moved slowly down over the convolution. Patient said, \"I heard my mother again, singing.\""},{"text":"3. Repeated 11 minutes after last stimulation at this point. \"I hear some kind of a machine. I saw it for a minute and heard it."},{"text":"3. Repeated fifteen minutes after last stimulation at this point, \"Nothing.\" When asked whether she ever heard people like her mother and father in any of her attacks, she said, \"Sometimes.\""}],"hotspots":[{"x":54.62,"y":53.9503}]},{"id":"4","events":[{"text":"4. She exclaimed \"Was that my mother yelling ?\" When asked after withdrawal of the electrode, she said, \"She was yelling at my little baby sister, Mary Jane.\" When asked if she saw them, she said she saw both distinctly. She said one was moving, but she could not remember which. \"Mary Jane had done something bad, and mother was telling her not to do it.\""},{"text":"4. Repeated five minutes after above stimulation at this point, the patient began to weep and said, \"It is coming. A spell. A fainting one.\""}],"hotspots":[]},{"id":"16","events":[{"text":"16. \"I hear my mother calling.\" When asked afterwards what she was calling, she said, \"Just yelling.\""}],"hotspots":[{"x":49.1058,"y":51.2415}]}]}]}
    </script>
