 "letter": "data:image/webp;base64,",
 "map-rw": "data:image/webp;base64,",
 "map-abra": "data:image/webp;base64,",
 "map-yn": "data:image/webp;base64,",
 "map-gp": "data:image/webp;base64,",
 "map-sbe": "data:image/webp;base64,",
 "map-nc": "data:image/webp;base64,",
 "map-ge": "data:image/webp;base64,"
}
    </script>

    <script>
      // The book injects window.OB before this runs; this fallback keeps the
      // file working on its own (in Claude, or opened in a browser).
      window.OB = window.OB || {
        reducedMotion:
          matchMedia("(prefers-reduced-motion: reduce)").matches ||
          document.documentElement.hasAttribute("data-ob-reduce-motion"),
        onTheme(fn) {
          fn({ accent: null, reduceMotion: this.reducedMotion, ramp: null });
        },
        maxHeight: null,
        onFit() {},
        resize() {},
      };

      const DATA = JSON.parse(document.getElementById("cases").textContent);
      const ASSETS = JSON.parse(document.getElementById("assets").textContent);
      const $ = (id) => document.getElementById(id);
      const el = (tag, attrs = {}, html = "") => {
        const n = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
        if (html) n.innerHTML = html;
        return n;
      };
      const esc = (s) =>
        String(s).replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]);

      // The seven patients, in the binder's order, each with its tab colour (Figma).
      const ORDER = ["ge", "sbe", "gp", "yn", "nc", "abra", "rw"];
      const COLOURS = {
        ge: "#9598df",
        sbe: "#8bb79e",
        gp: "#609bde",
        yn: "#f39033",
        nc: "#e7d347",
        abra: "#75bc73",
        rw: "#fb755b",
      };
      const CASES = ORDER.map((id) => DATA.cases.find((c) => c.id === id));

      // A point the verified data gives no place for, but the design marks on
      // the map (see "To check" at the top). x and y are per cent of the scan.
      const EXTRA_HOTSPOTS = { ge: { 4: [{ x: 52.16, y: 50.23 }] } };
      const hotspotsOf = (c, p) =>
        p.hotspots.length ? p.hotspots : EXTRA_HOTSPOTS[c.id]?.[p.id] || [];

      // Loose things in the binder (Figma 107:130, 107:131): centre, width and
      // tilt in the left page's pixels. Only `zoom` ones open large.
      const EPHEMERA = [
        {
          id: "letter",
          w: 199,
          cx: 298.9,
          cy: 512.5,
          rot: 6.58,
          zoom: false,
          label: "A typed letter. Drag to move it.",
        },
        {
          id: "photo",
          w: 300.4,
          cx: 157.9,
          cy: 358.8,
          rot: -10.12,
          zoom: true,
          label: "Photograph. Drag to move it, or press Enter to see it large.",
          alt: "A black and white photograph: about twenty people, most in white coats, sit and stand around a long table. Two men in suits at the front look at a tray of brain slices.",
        },
      ];

      const binder = $("binder");
      const left = $("left");
      const cover = $("cover");
      const state = { open: false, c: -1, p: null, busy: false };
      const reduced = () =>
        !!OB.reducedMotion ||
        document.documentElement.hasAttribute("data-ob-reduce-motion");

      $("coverImg").src = ASSETS.cover;
      $("probeImg").src = ASSETS.probe;
      $("cap").textContent = DATA.source.citation;

      /* ── Tabs ── */
      const tabs = CASES.map((c, i) => {
        const b = el(
          "button",
          {
            type: "button",
            class: "tab",
            "aria-pressed": "false",
            "aria-label": `Case ${c.caseNo}, ${c.tab}`,
            style: `--i:${i};--c:${COLOURS[c.id]}`,
          },
          `<span class="tab__b"><span class="tab__t"><b>${c.caseNo}</b><span class="tab__n"> ${esc(c.tab.replace(/\s+/g, ""))}</span></span></span>`
        );
        b.addEventListener("click", () => goTo(i));
        $("tabs").append(b);
        return b;
      });
      function paintTabs() {
        tabs.forEach((b, i) => {
          b.setAttribute("aria-pressed", String(state.open && i === state.c));
          b.classList.toggle(
            "is-left",
            state.open && i < state.c && binder.dataset.layout === "spread"
          );
        });
      }

      /* ── Rings (drawn once) ── */
      const RING =
        '<ellipse cx="22" cy="10" rx="17.5" ry="7.5" fill="none" stroke="#a1a1a1" stroke-width="5"/>';
      [66, 342, 616].forEach((y, n) => {
        const back = el("div", { class: "ring ring--back", style: `--y:${y + 10}` });
        back.innerHTML = `<svg viewBox="0 0 44 20" width="100%" height="100%" overflow="visible">${RING}</svg>`;
        const front = el("div", { class: "ring ring--front", style: `--y:${y + 10}` });
        front.innerHTML = `<svg viewBox="0 0 44 20" width="100%" height="100%" overflow="visible">
          <defs><clipPath id="rc${n}"><rect x="-2" y="-2" width="48" height="12.5"/><circle cx="5" cy="10" r="7"/><circle cx="39" cy="10" r="7"/></clipPath></defs>
          <circle class="hole hole--l" cx="5" cy="10" r="7" fill="#1c1c1c"/><circle cx="39" cy="10" r="7" fill="#1c1c1c"/>
          <g clip-path="url(#rc${n})">${RING}</g></svg>`;
        binder.prepend(back);
        binder.append(front);
      });

      /* ── The loose photograph and letter ── */
      let zTop = 4;
      const eph = EPHEMERA.map((e, n) => {
        const b = el(
          "button",
          {
            type: "button",
            class: "eph",
            "aria-label": e.label,
            style: `--cx:${e.cx};--cy:${e.cy};--w:${e.w};--rot:${e.rot}deg;--z:${n + 1}`,
          },
          `<img alt="" src="${ASSETS[e.id]}">`
        );
        const pos = { dx: 0, dy: 0 };
        const place = () => {
          b.style.setProperty("--dx", pos.dx.toFixed(1));
          b.style.setProperty("--dy", pos.dy.toFixed(1));
        };
        const clamp = () => {
          pos.dx = Math.max(-e.cx - 20, Math.min(472 - e.cx + 20, pos.dx));
          pos.dy = Math.max(-e.cy + 40, Math.min(698 - e.cy - 20, pos.dy));
        };
        let drag = null;
        b.addEventListener("pointerdown", (ev) => {
          if (ev.button) return;
          drag = { x: ev.clientX, y: ev.clientY, dx: pos.dx, dy: pos.dy, moved: false };
          b.setPointerCapture(ev.pointerId);
        });
        b.addEventListener("pointermove", (ev) => {
          if (!drag) return;
          const s = Number(binder.style.getPropertyValue("--s")) || 1;
          const mx = ev.clientX - drag.x;
          const my = ev.clientY - drag.y;
          if (!drag.moved && Math.hypot(mx, my) < 5) return;
          if (!drag.moved) {
            drag.moved = true;
            b.classList.add("is-drag");
            b.style.setProperty("--z", String(++zTop)); // pulled out: on top of the sheet
          }
          pos.dx = drag.dx + mx / s;
          pos.dy = drag.dy + my / s;
          clamp();
          place();
        });
        const end = () => {
          const d = drag;
          drag = null;
          b.classList.remove("is-drag");
          return d;
        };
        b.addEventListener("pointerup", () => {
          const d = end();
          if (d && !d.moved && e.zoom) openLightbox(e, b);
        });
        b.addEventListener("pointercancel", end);
        b.addEventListener("keydown", (ev) => {
          const step = { ArrowLeft: [-12, 0], ArrowRight: [12, 0], ArrowUp: [0, -12], ArrowDown: [0, 12] }[ev.key];
          if (step) {
            ev.preventDefault();
            b.style.setProperty("--z", String(++zTop));
            pos.dx += step[0];
            pos.dy += step[1];
            clamp();
            place();
          } else if ((ev.key === "Enter" || ev.key === " ") && e.zoom) {
            ev.preventDefault();
            openLightbox(e, b);
          }
        });
        left.prepend(b);
        return b;
      });

      /* ── The large photograph ── */
      let lbReturn = null;
      let lbFrom = null; // where the photograph lies in the binder, to fly from and back to
      function lbFlight() {
        const img = $("lbimg");
        const a = lbReturn?.getBoundingClientRect();
        const b = img.getBoundingClientRect();
        if (!a || !b.width || !lbReturn.offsetWidth) return null;
        const k = lbReturn.offsetWidth / b.width;
        const dx = a.left + a.width / 2 - (b.left + b.width / 2);
        const dy = a.top + a.height / 2 - (b.top + b.height / 2);
        return `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px) scale(${k.toFixed(4)}) rotate(${lbFrom.rot}deg)`;
      }
      function openLightbox(e, from) {
        lbReturn = from;
        lbFrom = e;
        $("lbimg").src = ASSETS[e.id];
        $("lbimg").alt = e.alt || "";
        $("lbcap").textContent = e.caption || "";
        $("lbcap").hidden = !e.caption;
        $("lb").hidden = false;
        $("lbx").focus();
        const flight = !reduced() && $("lb").animate && lbFlight();
        if (!flight) return;
        $("lbimg").animate([{ transform: flight }, { transform: "none" }], {
          duration: 420,
          easing: "cubic-bezier(0.2, 0.8, 0.2, 1)",
        });
        $("lb").animate(
          [{ backgroundColor: "rgba(28, 28, 28, 0)" }, { backgroundColor: "rgba(28, 28, 28, 0.86)" }],
          { duration: 300, easing: "ease-out" }
        );
      }
      let lbClosing = false;
      async function closeLightbox() {
        if ($("lb").hidden || lbClosing) return;
        const flight = !reduced() && $("lb").animate && lbFlight();
        if (flight) {
          lbClosing = true;
          $("lb").animate(
            [{ backgroundColor: "rgba(28, 28, 28, 0.86)" }, { backgroundColor: "rgba(28, 28, 28, 0)" }],
            { duration: 260, easing: "ease-in", fill: "forwards" }
          );
          await $("lbimg")
            .animate([{ transform: "none" }, { transform: flight }], {
              duration: 280,
              easing: "cubic-bezier(0.5, 0, 0.7, 0.4)",
              fill: "forwards",
            })
            .finished.catch(() => {});
          $("lb").getAnimations().forEach((a) => a.cancel());
          $("lbimg").getAnimations().forEach((a) => a.cancel());
          lbClosing = false;
        }
        $("lb").hidden = true;
        lbReturn?.focus();
      }
      $("lbx").addEventListener("click", closeLightbox);
      $("lb").addEventListener("click", (ev) => {
        if (ev.target === $("lb")) closeLightbox();
      });
      document.addEventListener("keydown", (ev) => {
        if (ev.key === "Escape") closeLightbox();
        // The dialog has one control: keep focus on it.
        if (ev.key === "Tab" && !$("lb").hidden) {
          ev.preventDefault();
          $("lbx").focus();
        }
      });

      /* ── The left page for a case: sheet, map, points ── */
      const MAP_W = 449; // the map's width on the sheet (Figma), px
      function mapBox(c) {
        const tall = c.image.height / c.image.width > 0.8;
        const sheetH = tall ? 670 : 450;
        let w = MAP_W;
        let h = (w * c.image.height) / c.image.width;
        const maxH = sheetH - (tall ? 24 : 99);
        if (h > maxH) {
          w = (w * maxH) / h;
          h = maxH;
        }
        const x = (455 - w) / 2;
        const y = tall ? (sheetH - h) / 2 : Math.min(89, sheetH - h - 10);
        return { tall, sheetH, x, y, w, h };
      }
      function drawLeft() {
        const c = CASES[state.c];
        const box = mapBox(c);
        left.toggleAttribute("data-tall", box.tall);
        left.style.setProperty("--sheet-h", box.sheetH);
        const map = $("map");
        map.style.cssText = `--mx:${box.x};--my:${box.y};--mw:${box.w};--mh:${box.h};--c:${COLOURS[c.id]}`;
        map.innerHTML = "";
        const names = c.points.map((p) => p.id).join(", ");
        map.append(
          el("img", {
            src: ASSETS["map-" + c.id],
            alt: `Penfield’s drawing of the brain for case ${c.caseNo}, ${c.tab}, with the stimulation points numbered: ${names}.`,
          })
        );
        for (const p of c.points)
          for (const h of hotspotsOf(c, p))
            map.append(
              el(
                "span",
                { class: "mk", "data-p": p.id, "aria-hidden": "true", style: `left:${h.x}%;top:${h.y}%` },
                "<i></i>"
              )
            );
        paintPoint();
      }
      // Where the probe's tip goes: the chosen point, in the left page's pixels.
      function pointXY(c, p) {
        const h = p && hotspotsOf(c, p)[0];
        if (!h) return null;
        const box = mapBox(c);
        return { h, x: 14 + box.x + (h.x / 100) * box.w, y: 15 + box.y + (h.y / 100) * box.h };
      }
      const probeAt = (x, y) =>
        `translate(calc(${x.toFixed(1)} * var(--u)), calc(${y.toFixed(1)} * var(--u)))`;
      const markOn = (on = true) =>
        $("map")
          .querySelectorAll(".mk")
          .forEach((m) => m.toggleAttribute("data-on", on && m.dataset.p === state.p));
      // Everything in its place at once (no motion).
      function paintPoint() {
        const c = CASES[state.c];
        if (!c) return;
        markOn();
        const at = pointXY(c, c.points.find((q) => q.id === state.p));
        const probe = $("probe");
        probe.classList.remove("is-air");
        if (!at) {
          probe.setAttribute("data-off", "");
          return;
        }
        probe.style.transform = probeAt(at.x, at.y);
        probe.removeAttribute("data-off");
      }
      // The probe put away and no point chosen on the map: how a page looks
      // while it turns, before the probe comes back to it.
      function restProbe() {
        $("probe").setAttribute("data-off", "");
        $("probe").classList.remove("is-air");
        markOn(false);
      }

      /* ── The stimulation: the probe travels to the point and touches it,
         rings spread from the point, and the report is typed on. ── */
      const wait = (ms) => new Promise((done) => setTimeout(done, ms));
      let act = 0; // the latest stimulation; an older one stops when a newer starts
      async function stimulate({ fromAfar = false } = {}) {
        const me = ++act;
        const c = CASES[state.c];
        const at = pointXY(c, c.points.find((q) => q.id === state.p));
        const probe = $("probe");
        const read = $("read");
        if (reduced() || !probe.animate) {
          paintPoint();
          read.removeAttribute("data-wait");
          return;
        }
        read.setAttribute("data-wait", "");
        markOn(false);
        if (at) {
          if (fromAfar || probe.hasAttribute("data-off")) {
            // It comes in along its own length, from beyond the top of the page.
            probe.style.transition = "none";
            probe.style.transform = probeAt(at.x + 170, at.y - 260);
            probe.getBoundingClientRect();
            probe.style.transition = "";
          }
          probe.classList.add("is-air");
          probe.removeAttribute("data-off");
          probe.style.transform = probeAt(at.x, at.y);
          await wait(460);
          if (me !== act) return;
          probe.classList.remove("is-air"); // touches down
          markOn();
          pulse(at.h);
          await wait(150);
          if (me !== act) return;
        } else restProbe(); // a point the map doesn't show: the probe is put away
        reveal();
      }
      function pulse(h) {
        for (const delay of [0, 170]) {
          const ring = el("span", {
            class: "pulse",
            "aria-hidden": "true",
            style: `left:${h.x}%;top:${h.y}%`,
          });
          $("map").append(ring);
          ring
            .animate(
              [
                { transform: "translate(-50%, -50%) scale(0.5)", opacity: 0.8 },
                { transform: "translate(-50%, -50%) scale(3.4)", opacity: 0 },
              ],
              { duration: 760, delay, easing: "cubic-bezier(0.2, 0.6, 0.3, 1)", fill: "both" }
            )
            .finished.catch(() => {})
            .then(() => ring.remove());
        }
      }
      // The heading is typed on, a letter at a time; the report follows.
      function reveal() {
        $("read").removeAttribute("data-wait");
        if (reduced() || !$("read").animate) return;
        let t = 0;
        for (const line of $("readh").children) {
          const n = Math.max(1, line.textContent.length);
          const ms = Math.min(440, n * 26);
          line.animate([{ clipPath: "inset(0 100% 0 0)" }, { clipPath: "inset(0 0 0 0)" }], {
            duration: ms,
            delay: t,
            easing: `steps(${n})`,
            fill: "backwards",
          });
          t += ms + 50;
        }
        [...$("report").children].forEach((para, i) =>
          para.animate(
            [
              { opacity: 0, transform: "translateY(8px)" },
              { opacity: 1, transform: "none" },
            ],
            {
              duration: 320,
              delay: Math.max(0, t - 160) + i * 80,
              easing: "cubic-bezier(0.2, 0.7, 0.2, 1)",
              fill: "backwards",
            }
          )
        );
      }

      // The point nearest the pointer, if it is within reach of one.
      function nearestMark(ev) {
        const s = Number(binder.style.getPropertyValue("--s")) || 1;
        const reach = Math.max(16, 18 * s);
        let best = null;
        let bestD = reach;
        for (const m of $("map").querySelectorAll(".mk")) {
          const r = m.getBoundingClientRect();
          const d = Math.hypot(ev.clientX - r.left, ev.clientY - r.top);
          if (d < bestD) {
            bestD = d;
            best = m;
          }
        }
        return best;
      }
      $("map").addEventListener("pointermove", (ev) => {
        const near = ev.pointerType === "mouse" ? nearestMark(ev) : null;
        $("map").toggleAttribute("data-near", !!near);
        $("map")
          .querySelectorAll(".mk")
          .forEach((m) => m.toggleAttribute("data-near", m === near));
      });
      $("map").addEventListener("pointerleave", () => {
        $("map").removeAttribute("data-near");
        $("map")
          .querySelectorAll(".mk[data-near]")
          .forEach((m) => m.removeAttribute("data-near"));
      });
      $("map").addEventListener("click", (ev) => {
        const near = nearestMark(ev);
        if (near) selectPoint(near.dataset.p);
      });

      /* ── The right page: what the patient reported at the chosen point ── */
      // The source numbers each report ("1c. After a pause…"): the heading
      // already says the point, so the number is dropped. Quoted speech is bold.
      function reportHtml(text, id) {
        const body = esc(text.replace(new RegExp("^\\s*" + id + "\\.\\s*", "i"), ""));
        return body.replace(/"[^"]*"/g, (q) => `<b>${q}</b>`);
      }
      // The page for a case: its list of points, then the chosen report.
      function drawRight() {
        const c = CASES[state.c];
        $("read").style.setProperty("--c", COLOURS[c.id]);
        $("ptsl").textContent = `Points in case ${c.caseNo}`;
        const row = $("pts");
        row.innerHTML = "";
        for (const q of c.points) {
          const b = el(
            "button",
            { type: "button", class: "pt", "data-p": q.id, "aria-pressed": "false", "aria-label": `Point ${q.id}` },
            esc(q.id)
          );
          b.addEventListener("click", () => selectPoint(q.id));
          row.append(b);
        }
        drawReport();
      }
      function drawReport() {
        const c = CASES[state.c];
        const p = c.points.find((q) => q.id === state.p) || c.points[0];
        $("readh").innerHTML =
          `<span>Point ${esc(p.id)}</span><span>Case ${c.caseNo}, ${esc(c.tab)}</span>`;
        const report = $("report");
        report.innerHTML =
          p.events.map((e) => `<p>${reportHtml(e.text, p.id)}</p>`).join("") +
          (hotspotsOf(c, p).length
            ? ""
            : `<p class="off-map">Point ${esc(p.id)} is not marked on the printed map.</p>`);
        report.scrollTop = 0;
        $("pts")
          .querySelectorAll(".pt")
          .forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.p === p.id)));
        more();
      }
      // Whether the report runs on below what shows.
      function more() {
        const r = $("report");
        r.toggleAttribute("data-more", r.scrollHeight - r.scrollTop - r.clientHeight > 6);
      }
      $("report").addEventListener("scroll", more, { passive: true });
      function selectPoint(id) {
        if (state.p === id) return;
        state.p = id;
        drawReport();
        stimulate();
        OB.resize();
      }

      /* ── Opening the binder and turning to a case ── */
      const right = document.querySelector(".page--right");
      // A copy of a page (or the cover) for the leaf, placed `x` Figma px from
      // its parent's left edge. It is a picture of the page: nothing in it can
      // be used or is read out.
      function copyOf(node, x) {
        const c = node.cloneNode(true);
        for (const n of [c, ...c.querySelectorAll("[id], [aria-live], [aria-label]")]) {
          n.removeAttribute("id");
          n.removeAttribute("aria-live");
          n.removeAttribute("aria-label");
        }
        c.setAttribute("aria-hidden", "true");
        c.inert = true;
        c.style.left = `calc(${x} * var(--u))`;
        c.style.visibility = "visible";
        return c;
      }
      // One leaf turns on the rings, from `from` to `to` degrees: 0 is flat on
      // the right, -180 flat on the left.
      async function turn({ front, back, from, to, ms, ghost }) {
        const leaf = el("div", { class: "leaf" });
        const shades = [front, back].map((face, n) => {
          face.classList.add("leaf__face");
          if (n) face.classList.add("leaf__face--back");
          const shade = el("div", { class: "leaf__shade" });
          face.append(shade);
          leaf.append(face);
          return shade;
        });
        const cast = el("div", { class: "cast" });
        if (ghost) {
          ghost.classList.add("ghost");
          binder.append(ghost);
        }
        binder.append(cast, leaf);
        const timing = { duration: ms, easing: "cubic-bezier(0.45, 0.05, 0.25, 1)", fill: "both" };
        // Each face is darkest edge on (half way), clear when it lies flat.
        const lit = (flatAt) => (from === flatAt ? [0, 1, 1] : [1, 1, 0]);
        shades.forEach((shade, n) =>
          shade.animate(
            lit(n ? -180 : 0).map((opacity, i) => ({ opacity: opacity * 0.5, offset: i / 2 })),
            timing
          )
        );
        cast.animate([{ opacity: 0 }, { opacity: 1, offset: 0.5 }, { opacity: 0 }], timing);
        await leaf
          .animate([{ transform: `rotateY(${from}deg)` }, { transform: `rotateY(${to}deg)` }], timing)
          .finished.catch(() => {});
        leaf.remove();
        cast.remove();
        ghost?.remove();
      }
      async function goTo(i) {
        if (state.busy || (state.open && i === state.c)) return;
        const from = state.c;
        const wasOpen = state.open;
        const spread = binder.dataset.layout === "spread";
        const still = reduced() || !binder.animate;
        // The pages as they are now, before anything is redrawn.
        const moving = wasOpen && spread && !still;
        const fwd = i > from;
        const oldLeft = moving ? copyOf(left, fwd ? 0 : 2) : null;
        const oldRight = moving ? copyOf(right, fwd ? 2 : 476) : null;
        const peeked = !wasOpen && getComputedStyle(cover).transform !== "none";
        const coverCopy = !wasOpen && spread && !still ? copyOf(cover, 2) : null;

        state.c = i;
        state.p = CASES[i].points[0].id;
        state.open = true;
        drawLeft();
        drawRight();
        if (still) {
          binder.dataset.open = "true";
          $("read").removeAttribute("data-wait");
          paintTabs();
          OB.resize();
          return;
        }
        restProbe();
        $("read").setAttribute("data-wait", "");
        if (!spread) {
          // Phones: no pages to turn; the probe and the report still arrive.
          binder.dataset.open = "true";
          paintTabs();
          OB.resize();
          stimulate({ fromAfar: true });
          return;
        }
        state.busy = true;
        try {
          if (!wasOpen) {
            // The cover swings over on the rings and lands as the left page,
            // while the binder slides across to make room for it.
            const back = copyOf(left, 2);
            left.style.visibility = "hidden";
            binder.dataset.open = "true";
            paintTabs();
            await turn({ front: coverCopy, back, from: peeked ? -7 : 0, to: -180, ms: 780 });
            left.style.visibility = "";
          } else {
            // Forward, the right page turns over and lands as the new left
            // page; back, the left page comes over as the new right one. The
            // page it leaves shows the new case at once; the page it lands on
            // keeps its old face until then.
            setTimeout(paintTabs, 330);
            await turn(
              fwd
                ? { front: oldRight, back: copyOf(left, 2), from: 0, to: -180, ms: 680, ghost: oldLeft }
                : { front: copyOf(right, 2), back: oldLeft, from: -180, to: 0, ms: 680, ghost: oldRight }
            );
          }
        } finally {
          state.busy = false;
          paintTabs();
          OB.resize();
        }
        stimulate({ fromAfar: true });
      }

      // Once, when the closed binder first comes into view: the tabs stir, top
      // to bottom, to say they can be pressed.
      function invite() {
        if (state.open || reduced() || !binder.animate) return;
        const s = Number(binder.style.getPropertyValue("--s")) || 1;
        const stack = binder.dataset.layout === "stack";
        const nudge = stack ? `translateY(${-4}px)` : `translateX(${(9 * s).toFixed(1)}px)`;
        tabs.forEach((b, n) =>
          b.querySelector(".tab__b").animate(
            [{ transform: "none" }, { transform: nudge, offset: 0.4 }, { transform: "none" }],
            { duration: 520, delay: 350 + n * 75, easing: "ease-in-out" }
          )
        );
      }
      if ("IntersectionObserver" in window) {
        const seen = new IntersectionObserver(
          (entries) => {
            if (!entries.some((entry) => entry.isIntersecting)) return;
            seen.disconnect();
            invite();
          },
          { threshold: 0.5 }
        );
        seen.observe(cover);
      } else setTimeout(invite, 600);

      /* ── Fitting the space there is ── */
      const stage = $("stage");
      const w = $("w");
      function layout() {
        const fit = document.documentElement.hasAttribute("data-ob-fit");
        const W = stage.clientWidth;
        const stack = W < 700;
        const cap = $("cap");
        // The source line sits in the corner when there is room beside the
        // binder. Decided from the height the binder would have with the line
        // out of the way, which is the same whichever place the line is in
        // now, so the choice cannot flip back and forth.
        let side = false;
        if (fit && !stack) {
          const inFlow = w.dataset.cap !== "side";
          const gap = parseFloat(getComputedStyle(w).rowGap) || 0;
          const roomy = stage.clientHeight + (inFlow ? cap.offsetHeight + gap : 0);
          const sSide = Math.max(0.45, Math.min(1.25, W / 1016, roomy / 698));
          const beside = (W - 1016 * sSide) / 2 - 12;
          side = beside >= 180;
          if (side) w.style.setProperty("--cap-w", Math.min(beside, 560) + "px");
        }
        if (side) w.dataset.cap = "side";
        else delete w.dataset.cap;
        let s;
        if (stack) s = Math.min(1, W / 472);
        else {
          // 944 of pages, tabs to the right, tabs and the photograph to the left
          s = W / 1016;
          if (fit && stage.clientHeight > 0) s = Math.min(s, stage.clientHeight / 698);
          s = Math.max(0.45, Math.min(1.25, s));
        }
        binder.dataset.layout = stack ? "stack" : "spread";
        w.toggleAttribute("data-stack", stack);
        binder.style.setProperty("--s", s.toFixed(4));
        binder.toggleAttribute("data-compact", !stack && s < 0.6);
        paintTabs();
        more();
      }
      new ResizeObserver(() => {
        layout();
        OB.resize();
      }).observe(stage);
      OB.onFit(() => {
        layout();
        // The stage's height changes after the caption moves: measure again.
        requestAnimationFrame(() => {
          layout();
          OB.resize();
        });
      });
      OB.onTheme(() => {});
      layout();
      paintTabs();
      OB.resize();
      requestAnimationFrame(() => requestAnimationFrame(() => binder.setAttribute("data-ready", "")));
    </script>
  </body>
</html>
$w$,
  'published'
)
on conflict (slug) do update
  set title = excluded.title, description = excluded.description, author = excluded.author,
      ramp = excluded.ramp, html = excluded.html, status = excluded.status, updated_at = now();

-- 2. The Penfield block: the cabinet becomes the binder.
update public.paragraphs p
set content = jsonb_set(p.content, '{blocks}', (
  select jsonb_agg(
    case when b->>'type' = 'widget' and b->>'widgetId' = 'case-cabinet'
      then (b - 'route') || jsonb_build_object(
        'widgetId', 'upload:history-penfield-binder',
        'kind', 'inline',
        'fullScreen', true)
      else b end order by ordinal
  )
  from jsonb_array_elements(p.content->'blocks') with ordinality as blocks(b, ordinal)
)), updated_at = now()
from public.sections s join public.modules m on m.id = s.module_id
where p.section_id = s.id
  and m.slug = 'foundations-of-neuroscience'
  and jsonb_typeof(p.content->'blocks') = 'array'
  and p.content->'blocks' @> '[{"type":"widget","widgetId":"case-cabinet"}]'::jsonb;

-- 3. The phrenology block says it is one screen too.
update public.paragraphs p
set content = jsonb_set(p.content, '{blocks}', (
  select jsonb_agg(
    case when b->>'type' = 'widget' and b->>'widgetId' = 'phrenology' and not (b ? 'fullScreen')
      then b || jsonb_build_object('fullScreen', true)
      else b end order by ordinal
  )
  from jsonb_array_elements(p.content->'blocks') with ordinality as blocks(b, ordinal)
)), updated_at = now()
from public.sections s join public.modules m on m.id = s.module_id
where p.section_id = s.id
  and m.slug = 'foundations-of-neuroscience'
  and jsonb_typeof(p.content->'blocks') = 'array'
  and p.content->'blocks' @> '[{"type":"widget","widgetId":"phrenology"}]'::jsonb
  and not (p.content->'blocks' @> '[{"type":"widget","widgetId":"phrenology","fullScreen":true}]'::jsonb);
